      "id": 9,
      "pergunta": "QUESTÃO 09) De todas as transformações impostas pelo meio técnico-científico-informacional à logística de transportes, interessa-nos mais de perto a intermodalidade. E por uma razão muito simples: o potencial que tal “ferramenta logística” ostenta permite que haja, de fato, um sistema de transportes condizente com a escala geográfica do Brasil.\nHUERTAS, D. M. O papel dos transportes na expansão recente da fronteira agrícola brasileira. A necessidade de modais de transporte interligados, no território brasileiro, justifica-se pela(s)",
