      "id": 38,
      "pergunta": "QUESTÃO 38) A recuperação da herança cultural africana deve levar em conta o que é próprio do processo cultural: seu movimento, pluralidade e complexidade. Não se trata, portanto, do resgate ingênuo do passado nem do seu cultivo nostálgico, mas de procurar perceber o próprio rosto cultural brasileiro. O que se quer é captar seu movimento para melhor compreendê-lo historicamente.\nMINAS GERAIS. Cadernos do Arquivo 1: Escravidão em Minas Gerais.\nBelo Horizonte: Arquivo Público Mineiro, 1988.\nCom base no texto, a análise de manifestações culturais de origem africana, como a capoeira ou o candomblé, deve considerar que elas",
