      "id": 53,
      "pergunta": "Dizem que Humboldt, naturalista do século XIX, maravilhado pela geografia, flora e fauna da região sul-americana, via seus habitantes como se fossem mendigos sentados sobre um saco de ouro, referindo-se a suas incomensuráveis riquezas naturais não exploradas. De alguma maneira, o cientista ratificou nosso papel de exportadores de natureza no que seria o mundo depois da colonização ibérica: enxergou-nos como territórios condenados a aproveitar os recursos naturais existentes.\nACOSTA, A. Bem viver: uma oportunidade para imaginar outros mundos. A relação entre ser humano e natureza ressaltada no texto refletia a permanência da seguinte corrente filosófica:",
