      "id": 39,
      "pergunta": "QUESTÃO 39) Pesca industrial provoca destruição na África súbito desaparecimento do bacalhau dos grandes cardumes da Terra Nova, no ﬁnal do século XX — o que ninguém havia previsto —, teve o efeito de um eletrochoque planetário. Lançada pelos bascos no século XV, a pesca e depois a sobrepesca desse grande peixe de água fria levaram ao impensável. Ao Canadá o bacalhau nunca mais voltou. E o que ocorreu no Atlântico Norte está acontecendo em outros mares. Os maiores navios do mundo seguem agora em direção ao sul, até os limites da Antártida, para competir pelos estoques remanescentes.\nO problema exposto no texto jornalístico relaciona-se à",
