      "id": 41,
      "pergunta": "QUESTÃO 41) Ser moderno é encontrar-se em um ambiente que promete aventura, poder, alegria, crescimento, autotransformação e transformação das coisas em redor — mas ao mesmo tempo ameaça destruir tudo o que temos, tudo o que sabemos, tudo o que somos. A experiência ambiental da modernidade anula todas as fronteiras geográﬁcas e raciais, de classe e nacionalidade: nesse sentido, pode-se dizer que a modernidade une a espécie humana. Porém, é uma unidade paradoxal, uma unidade de desunidade.\nBERMAN, M. Tudo que é sólido desmancha no ar: a aventura da modernidade.\nO texto apresenta uma interpretação da modernidade que a caracteriza como um(a)",
