      "id": 3,
      "pergunta": "QUESTÃO 03) Apesar de seu disfarce de iniciativa e otimismo, o homem moderno está esmagado por um profundo sentimento de impotência que o faz olhar fixamente e, como que paralisado, para as catástrofes que se avizinham. Por isso, desde já, saliente-se a necessidade de uma permanente atitude crítica, o único modo pelo qual o homem realizará sua vocação natural de integrar-se, superando a atitude do simples ajustamento ou acomodação, apreendendo temas e tarefas de sua época.\nFREIRE, P. Educação como prática da liberdade. Rio de Janeiro: Paz e Terra, 2011.\nPaulo Freire defende que a superação das dificuldades e a apreensão da realidade atual será obtida pelo(a)",
