      "id": 37,
      "pergunta": "QUESTÃO 37) No início foram as cidades. O intelectual da Idade Média — no Ocidente — nasceu com elas. Foi com o desenvolvimento urbano ligado às funções comercial e industrial — digamos modestamente artesanal — que ele apareceu, como um desses homens de ofício que se instalavam nas cidades nas quais se impôs a divisão do trabalho. Um homem cujo ofício é escrever ou ensinar, e de preferência as duas coisas a um só tempo, um homem que, profissionalmente, tem uma atividade de professor e erudito, em resumo, um intelectual — esse homem só aparecerá com as cidades.\nLE GOFF, J. Os intelectuais na Idade Média. Rio de Janeiro: José Olympio, 2010.\nO surgimento da categoria mencionada no período em destaque no texto evidencia o(a)",
