      "id": 42,
      "pergunta": "QUESTÃO 42) Ninguém nasce mulher: torna-se mulher. Nenhum destino biológico, psíquico, econômico define a forma que a fêmea humana assume no seio da sociedade; é o conjunto da civilização que elabora esse produto intermediário entre o macho e o castrado que qualificam o feminino.\nBEAUVOIR, S. O segundo sexo. Rio de Janeiro: Nova Fronteira, 1980.\nNa década de 1960, a proposição de Simone de Beauvoir contribuiu para estruturar um movimento social que teve como marca o(a)",
