      "pergunta": "QUESTÃO 04) A Floresta Amazônica, com toda a sua imensidão, não vai estar aí para sempre. Foi preciso alcançar toda essa taxa de desmatamento de quase 20 mil quilômetros quadrados ao ano, na última década do século XX, para que uma pequena parcela de brasileiros se desse conta de que o maior patrimônio natural do país está sendo torrado.\nAB’SABER, A. Amazônia: do discurso à práxis. São Paulo: EdUSP, 1996. Um processo econômico que tem contribuído na atualidade para acelerar o problema ambiental descrito é:",
