      "id": 18,
      "pergunta": "QUESTÃO 18) Na década de 1990, os movimentos sociais camponeses e as ONGs tiveram destaque, ao lado de outros sujeitos coletivos. Na sociedade brasileira, a ação dos movimentos sociais vem construindo lentamente um conjunto de práticas democráticas no interior das escolas, das comunidades, dos grupos organizados e na interface da sociedade civil com o Estado. O diálogo, o confronto e o conflito têm sido os motores no processo de construção democrática.\nSOUZA, M. A. Movimentos sociais no Brasil contemporâneo: participação e possibilidades das Segundo o texto, os movimentos sociais contribuem para o processo de construção democrática, porque",
