      "pergunta": "QUESTÃO 19) Art. 92. São excluídos de votar nas Assembleias Paroquiais: I. Os menores de vinte e cinco anos, nos quais não se compreendam os casados, e Oficiais Militares, que forem maiores de vinte e um anos, os Bacharéis Formados e Clérigos de Ordens Sacras.\nIV. Os Religiosos, e quaisquer que vivam em Comunidade claustral.\nV. Os que não tiverem de renda líquida anual cem mil réis por bens de raiz, indústria, comércio ou empregos.\nConstituição Política do Império do Brasil (1824). A legislação espelha os conflitos políticos e sociais do contexto histórico de sua formulação. A Constituição de 1824 regulamentou o direito de voto dos “cidadãos brasileiros” com o objetivo de garantir",
